BEGIN TRANSACTION;
IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20261011183246_PracticeExpansionAndExams'
)
BEGIN
    CREATE TABLE [learning].[BankSessions] (
        [Id] uniqueidentifier NOT NULL,
        [UserId] nvarchar(450) NOT NULL,
        [Mode] nvarchar(16) NOT NULL,
        [Form] nvarchar(40) NOT NULL,
        [Edition] int NOT NULL,
        [StartedAt] datetimeoffset NOT NULL,
        [Deadline] datetimeoffset NULL,
        [CompletedAt] datetimeoffset NULL,
        [RestartedFromId] uniqueidentifier NULL,
        [Revision] int NOT NULL,
        CONSTRAINT [PK_BankSessions] PRIMARY KEY ([Id]),
        CONSTRAINT [FK_BankSessions_AspNetUsers_UserId] FOREIGN KEY ([UserId]) REFERENCES [AspNetUsers] ([Id]) ON DELETE NO ACTION
    );
END;

IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20261011183246_PracticeExpansionAndExams'
)
BEGIN
    CREATE TABLE [learning].[BankSessionSteps] (
        [SessionId] uniqueidentifier NOT NULL,
        [Position] int NOT NULL,
        [ContentId] uniqueidentifier NOT NULL,
        [Section] nvarchar(16) NOT NULL,
        [Stage] nvarchar(16) NOT NULL,
        [Kind] nvarchar(40) NOT NULL,
        [Excluded] bit NOT NULL,
        [SubmissionId] uniqueidentifier NULL,
        [SubmittedAt] datetimeoffset NULL,
        [Scores] nvarchar(100) NOT NULL,
        [Maximum] int NOT NULL,
        [NeedsEvaluation] bit NOT NULL,
        [TimedOut] bit NOT NULL,
        CONSTRAINT [PK_BankSessionSteps] PRIMARY KEY ([SessionId], [Position]),
        CONSTRAINT [FK_BankSessionSteps_BankSessions_SessionId] FOREIGN KEY ([SessionId]) REFERENCES [learning].[BankSessions] ([Id]) ON DELETE NO ACTION
    );
END;

