IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20261011183246_PracticeExpansionAndExams'
)
BEGIN
    IF EXISTS (SELECT * FROM [sys].[identity_columns] WHERE [name] IN (N'Id', N'Format', N'ItemsJson', N'Module', N'Position', N'PublicationStatus', N'Text', N'Title', N'Version') AND [object_id] = OBJECT_ID(N'[content].[ReadingSetVersions]'))
        SET IDENTITY_INSERT [content].[ReadingSetVersions] ON;
    EXEC(N'INSERT INTO [content].[ReadingSetVersions] ([Id], [Format], [ItemsJson], [Module], [Position], [PublicationStatus], [Text], [Title], [Version])
    VALUES (''0f46ccb9-e8ce-4fc9-8182-a58549fe329d'', N''notice'', N''[{"Id":1,"Prompt":"What can a visitor do at 18:30 on Friday?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Buy a hot meal"},{"Id":"B","Text":"Visit every exhibition with one ticket"},{"Id":"C","Text":"Visit the permanent collection at a reduced price"},{"Id":"D","Text":"Enter the textile exhibition"}],"Answer":"C","Explanation":"The permanent collection remains open and discounted; textiles and hot meals have closed."},{"Id":2,"Prompt":"Which benefit for members remains unchanged?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Free meals on Fridays"},{"Id":"B","Text":"Extended access to the textile exhibition"},{"Id":"C","Text":"A discount on all separate tickets"},{"Id":"D","Text":"Free entry to the permanent collection"}],"Answer":"D","Explanation":"The final sentence explicitly preserves members\u0027 free permanent-collection admission."}]'', N''daily-life'', 9, 2, CONCAT(CAST(N''FRIDAY EVENINGS AT THE RIVER MUSEUM'' AS nvarchar(max)), nchar(10), N''From 4 April, the permanent collection will stay open until 20:00 on Fridays. Admission after 17:00 is half the usual price. The special textile exhibition closes at 17:00 and requires a separate ticket at all times. The café serves drinks until 19:30; hot meals finish at 18:00. Members enter the permanent collection free as usual.''), N''Museum late opening'', 3),
    (''20d702fd-6198-43ef-8beb-bbc7288fa9f5'', N''notice'', N''[{"Id":1,"Prompt":"Which item is no longer needed?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Sturdy shoes"},{"Id":"B","Text":"Advance notice of access needs"},{"Id":"C","Text":"A tide chart"},{"Id":"D","Text":"A packed lunch"}],"Answer":"C","Explanation":"The destination changed from the coast, and the message explicitly removes the tide chart."},{"Id":2,"Prompt":"Why should some students contact Dr. Ellis by Tuesday?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To change the bus departure time"},{"Id":"B","Text":"To order lunch for everyone"},{"Id":"C","Text":"To register for a different seminar"},{"Id":"D","Text":"To arrange a suitable route"}],"Answer":"D","Explanation":"Advance notice lets quarry staff organize an accessible route."}]'', N''daily-life'', 7, 2, CONCAT(CAST(N''To: Geology seminar'' AS nvarchar(max)), nchar(10), N''Subject: Thursday field visit'', nchar(10), N''The coastal path is closed for maintenance, so we will visit the inland quarry instead. The bus still leaves at 8:30 from the science building. You will not need the tide chart listed on the original checklist. Bring a packed lunch and sturdy shoes. Please tell me by Tuesday if you require an accessible route; the quarry staff can arrange one with advance notice.'', nchar(10), N''Dr. Ellis''), N''Field trip update'', 3),
    (''2be42540-8ebe-dd1a-629f-1c278f97d796'', N''notice'', N''[{"Id":1,"Prompt":"Where should students collect reserved books?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"At the ground-floor desk"},{"Id":"B","Text":"At the second-floor office"},{"Id":"C","Text":"At the main entrance"},{"Id":"D","Text":"At their department"}],"Answer":"A","Explanation":"Duyuru, teslim noktas\u0131n\u0131n ground-floor desk olarak de\u011Fi\u015Fti\u011Fini a\u00E7\u0131k\u00E7a s\u00F6yl\u00FCyor."},{"Id":2,"Prompt":"What should a student do if unable to collect a book on time?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Reserve another copy"},{"Id":"B","Text":"Call after three days"},{"Id":"C","Text":"Reply before the deadline"},{"Id":"D","Text":"Visit the old office"}],"Answer":"C","Explanation":"S\u00FCre uzat\u0131m\u0131 i\u00E7in son tarihten \u00F6nce e-postaya yan\u0131t verilmesi isteniyor."}]'', N''daily-life'', 1, 2, CONCAT(CAST(N''LIBRARY NOTICE'' AS nvarchar(max)), nchar(10), N''Reserved books are now collected from the ground-floor desk, not the second-floor office. Bring your student card. Items are held for three working days after the email notification. If you cannot collect yours in time, reply to the email before the deadline to request an extension.''), N''Library pickup notice'', 3),
    (''2ccdfc6f-d8ea-ca61-5ef5-538a83551ca2'', N''article'', N''[{"Id":1,"Prompt":"What is the passage mainly concerned with?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Using lake sediment to investigate past environments"},{"Id":"B","Text":"Predicting the exact date of future fires"},{"Id":"C","Text":"Removing all sediment from lakes"},{"Id":"D","Text":"Showing that pollen is useless"}],"Answer":"A","Explanation":"Katmanlardaki kan\u0131tlar\u0131n \u00E7evre tarihini anlamada kullan\u0131m\u0131 ve yorum s\u0131n\u0131rlar\u0131 anlat\u0131l\u0131yor."},{"Id":2,"Prompt":"What is generally true of deeper sediment?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"It contains no pollen"},{"Id":"B","Text":"It is always grass"},{"Id":"C","Text":"It is older"},{"Id":"D","Text":"It has no environmental value"}],"Answer":"C","Explanation":"\u0130lk paragraf derindeki malzemenin genellikle daha eski oldu\u011Funu belirtir."},{"Id":3,"Prompt":"Why might an increase in grass pollen be difficult to interpret?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Grass never produces pollen"},{"Id":"B","Text":"More than one process could explain it"},{"Id":"C","Text":"Trees cannot grow near lakes"},{"Id":"D","Text":"All pollen has the same age"}],"Answer":"B","Explanation":"\u0130klim de\u011Fi\u015Fimi veya insan\u0131n arazi a\u00E7mas\u0131 ayn\u0131 \u00F6r\u00FCnt\u00FCy\u00FC olu\u015Fturabilir."},{"Id":4,"Prompt":"The word \u0027indicator\u0027 is closest in meaning to","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"instruction"},{"Id":"B","Text":"container"},{"Id":"C","Text":"obstacle"},{"Id":"D","Text":"sign"}],"Answer":"D","Explanation":"Ge\u00E7mi\u015F ko\u015Fullar hakk\u0131nda ipucu ya da belirti anlam\u0131nda kullan\u0131l\u0131yor."},{"Id":5,"Prompt":"Why does the author contrast sediment with a precise diary?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To claim scientists should use diaries only"},{"Id":"B","Text":"To emphasize that interpretation involves uncertainty"},{"Id":"C","Text":"To argue that deeper layers are always younger"},{"Id":"D","Text":"To dismiss historical records"}],"Answer":"B","Explanation":"Tarihleme ve neden belirleme belirsiz oldu\u011Fu i\u00E7in katmanlar kesin g\u00FCnl\u00FCk gibi okunamaz."}]'', N''academic-passage'', 5, 2, CONCAT(CAST(N''Material gradually settles on the bottoms of lakes, forming layers of sediment. These layers may contain pollen, mineral particles, and remains of small organisms. By removing a narrow column of sediment, researchers can examine a sequence in which deeper material is generally older than material near the surface. The column acts as a partial record of the surrounding environment.'' AS nvarchar(max)), nchar(10), nchar(10), N''Pollen offers clues about plants that grew nearby. If pollen from trees becomes less common while grass pollen increases, the landscape may have become more open. However, the change could reflect either a shift in climate or human activities such as clearing land. A single indicator rarely identifies the cause with certainty.'', nchar(10), nchar(10), N''Researchers strengthen interpretations by comparing pollen with other evidence, including charcoal particles and historical records. Charcoal may indicate burning, though it does not reveal by itself whether the fire was natural or deliberately started. Establishing the age of each layer also involves uncertainty. Rather than treating sediment as a precise diary, scientists combine several lines of evidence to build and revise explanations of environmental change over time.''), N''A record written in lake sediment'', 3),
    (''3adb0545-ea1c-4e2b-8af5-778f5a0b9dec'', N''notice'', N''[{"Id":1,"Prompt":"What must a student bring?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Replacement parts"},{"Id":"B","Text":"A workbench"},{"Id":"C","Text":"All necessary tools"},{"Id":"D","Text":"A printed campus map"}],"Answer":"A","Explanation":"The notice provides tools but asks riders to supply parts."},{"Id":2,"Prompt":"What does the Wednesday volunteer offer?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Longer booking periods"},{"Id":"B","Text":"Guidance while riders perform repairs"},{"Id":"C","Text":"A complete repair service"},{"Id":"D","Text":"Free replacement bicycles"}],"Answer":"B","Explanation":"The volunteer demonstrates repairs rather than doing them for owners."}]'', N''daily-life'', 6, 2, CONCAT(CAST(N''BICYCLE REPAIR STATION'' AS nvarchar(max)), nchar(10), N''Students may reserve a workbench for 45 minutes through the campus app. Tools are provided, but please bring any replacement parts you need. A volunteer is available on Wednesdays to demonstrate simple repairs; the volunteer does not repair bicycles on behalf of their owners. Cancel at least two hours before your booking so another rider can use the space.''), N''Repair station reservation'', 3),
    (''4774fda7-53c8-4543-8077-e819d1b464a0'', N''article'', N''[{"Id":1,"Prompt":"What central claim does the author make?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Pauses always indicate recording faults"},{"Id":"B","Text":"Longer silence is always more effective"},{"Id":"C","Text":"Musical patterns have no effect on listeners"},{"Id":"D","Text":"Silence can contribute to musical meaning"}],"Answer":"D","Explanation":"The passage explains anticipation and phrase separation as functions of silence."},{"Id":2,"Prompt":"Why compare silence at the beginning and after a familiar sequence?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To show that prior context changes its effect"},{"Id":"B","Text":"To prove all recordings should begin silently"},{"Id":"C","Text":"To rank instruments by loudness"},{"Id":"D","Text":"To show listeners ignore familiar patterns"}],"Answer":"A","Explanation":"The examples hold silence length constant but change what the listener has heard."},{"Id":3,"Prompt":"The word \u0022anticipation\u0022 is closest in meaning to","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"exhaustion"},{"Id":"B","Text":"expectation"},{"Id":"C","Text":"confusion"},{"Id":"D","Text":"measurement"}],"Answer":"B","Explanation":"A familiar pattern creates an expectation about the next sound."},{"Id":4,"Prompt":"Why keep other features similar in an experiment?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To eliminate pauses from the recording"},{"Id":"B","Text":"To test which equipment is most expensive"},{"Id":"C","Text":"To isolate the effect of pause placement"},{"Id":"D","Text":"To make every listener choose the same answer"}],"Answer":"C","Explanation":"Matched passages reduce alternative explanations for different responses."},{"Id":5,"Prompt":"What can be inferred about a technical interruption?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"It necessarily improves anticipation"},{"Id":"B","Text":"It has the same effect as every planned pause"},{"Id":"C","Text":"It makes contextual information irrelevant"},{"Id":"D","Text":"It may draw attention away from musical structure"}],"Answer":"D","Explanation":"Listeners may focus on faulty equipment instead of the composition."}]'', N''academic-passage'', 7, 2, CONCAT(CAST(N''A pause in music may seem to be an absence of activity. Yet listeners often experience silence as an important part of a musical phrase. After a repeated pattern establishes an expectation, a brief pause can delay its completion. When the expected sound finally arrives, the delay can make it feel especially significant.'' AS nvarchar(max)), nchar(10), nchar(10), N''This effect depends partly on what has already been heard. A silence at the beginning of an unfamiliar recording offers few clues about what will follow. The same length of silence after a familiar sequence may create strong anticipation. Duration alone therefore does not explain the experience; the surrounding pattern matters. Musicians can also use pauses to separate phrases, giving listeners time to recognize one unit before another begins.'', nchar(10), nchar(10), N''Researchers who study these effects must distinguish musical expectation from practical interruptions. If a recording suddenly stops because of a technical fault, listeners may attend to the equipment rather than the composition. In experiments, researchers can present several carefully matched versions of a passage, altering where a pause occurs while keeping other features similar. Differences in listeners'''' responses then help reveal how timing contributes to musical structure. Silence, in this view, is not merely empty space between notes but a feature whose meaning emerges from its context.''), N''The hidden work of a musical pause'', 3),
    (''4b3c67e5-19f2-b5c9-a8f6-a6f1a5841156'', N''paragraph'', N''[{"Id":1,"Prompt":"Fill in the missing letters.","Prefix":"wor","MissingLetters":3,"Options":[],"Answer":"ker","Explanation":"worker: A sonras\u0131nda tekil isim."},{"Id":2,"Prompt":"Fill in the missing letters.","Prefix":"ho","MissingLetters":2,"Options":[],"Answer":"me","Explanation":"home: returns ile d\u00F6n\u00FC\u015F yerini belirtir."},{"Id":3,"Prompt":"Fill in the missing letters.","Prefix":"fin","MissingLetters":4,"Options":[],"Answer":"ding","Explanation":"finding: after sonras\u0131nda -ing bi\u00E7imi."},{"Id":4,"Prompt":"Fill in the missing letters.","Prefix":"a","MissingLetters":2,"Options":[],"Answer":"nd","Explanation":"and: iki eylemi ba\u011Flar."},{"Id":5,"Prompt":"Fill in the missing letters.","Prefix":"move","MissingLetters":5,"Options":[],"Answer":"ments","Explanation":"movements: performs fiilinin nesnesi."},{"Id":6,"Prompt":"Fill in the missing letters.","Prefix":"indi","MissingLetters":4,"Options":[],"Answer":"cate","Explanation":"indicate: \u00E7o\u011Ful movements ile uyumlu fiil."},{"Id":7,"Prompt":"Fill in the missing letters.","Prefix":"wh","MissingLetters":3,"Options":[],"Answer":"ile","Explanation":"while: e\u015Fzamanl\u0131 eylemleri ba\u011Flar."},{"Id":8,"Prompt":"Fill in the missing letters.","Prefix":"be","MissingLetters":2,"Options":[],"Answer":"es","Explanation":"bees: other sonras\u0131nda \u00E7o\u011Ful isim."},{"Id":9,"Prompt":"Fill in the missing letters.","Prefix":"a","MissingLetters":2,"Options":[],"Answer":"nd","Explanation":"and: watch ve receive eylemlerini ba\u011Flar."},{"Id":10,"Prompt":"Fill in the missing letters.","Prefix":"use","MissingLetters":3,"Options":[],"Answer":"ful","Explanation":"useful: information ismini niteler."}]'', N''complete-words'', 4, 2, N''Honeybees share information about food with other members of their colony. A {{1}} returns {{2}} after {{3}} flowers {{4}} performs {{5}} that {{6}} direction {{7}} other {{8}} watch {{9}} receive {{10}} information. The pattern gives nearby workers clues about where they should search. The message is not a map with exact coordinates. Wind, the quality of the food, and the distance from the colony can affect a bee''''s journey. Researchers observe repeated trips to understand how the colony responds to changing conditions.'', N''Signals in a bee colony'', 3),
    (''6315129c-ce48-f6fe-a506-d3be04758083'', N''article'', N''[{"Id":1,"Prompt":"What is the passage mainly about?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Why rural areas need paved roads"},{"Id":"B","Text":"How trees cool cities and what supports their success"},{"Id":"C","Text":"Why cities should stop planting trees"},{"Id":"D","Text":"How to measure the age of a tree"}],"Answer":"B","Explanation":"Metin so\u011Futma mekanizmalar\u0131n\u0131, k\u0131s\u0131tlar\u0131 ve uzun vadeli dikim tasar\u0131m\u0131n\u0131 birle\u015Ftiriyor."},{"Id":2,"Prompt":"How does evaporation help cool the air?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"It prevents all rainfall"},{"Id":"B","Text":"It releases stored solar energy"},{"Id":"C","Text":"It takes heat from the air"},{"Id":"D","Text":"It increases road temperature"}],"Answer":"C","Explanation":"\u0130lk paragraf buharla\u015Fan suyun \u00E7evredeki havadan \u0131s\u0131 ald\u0131\u011F\u0131n\u0131 belirtiyor."},{"Id":3,"Prompt":"The word \u0027constraints\u0027 is closest in meaning to","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"celebrations"},{"Id":"B","Text":"measurements"},{"Id":"C","Text":"predictions"},{"Id":"D","Text":"limitations"}],"Answer":"D","Explanation":"Su gereksinimi ve iklim gibi ba\u015Far\u0131y\u0131 s\u0131n\u0131rlayan ko\u015Fullara g\u00F6nderme yap\u0131l\u0131yor."},{"Id":4,"Prompt":"Why does the author mention permeable paving?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To give an example of supporting tree survival"},{"Id":"B","Text":"To argue that shade is unnecessary"},{"Id":"C","Text":"To describe a rural farming method"},{"Id":"D","Text":"To show that roots should remain dry"}],"Answer":"A","Explanation":"Ge\u00E7irgen y\u00FCzey, a\u011Fa\u00E7lar\u0131 \u00E7evre sistemiyle birlikte planlaman\u0131n \u00F6rne\u011Fi."},{"Id":5,"Prompt":"What can be inferred about counting newly planted trees?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"It always measures cooling accurately"},{"Id":"B","Text":"It is sufficient for planning"},{"Id":"C","Text":"It does not alone show long-term benefits"},{"Id":"D","Text":"It proves that trees will survive"}],"Answer":"C","Explanation":"Son paragraf say\u0131dan \u00E7ok ya\u015Fama ko\u015Fullar\u0131n\u0131n \u00F6nemli oldu\u011Funu vurguluyor."}]'', N''academic-passage'', 1, 2, CONCAT(CAST(N''Cities are often warmer than nearby rural areas because roads and buildings absorb solar energy and release it slowly. Trees can reduce this local warming in two ways. Their leaves shade surfaces, preventing some energy from reaching the ground. Trees also release water through their leaves; as this water evaporates, it takes heat from the surrounding air.'' AS nvarchar(max)), nchar(10), nchar(10), N''The benefits are unevenly distributed. A single tree beside a wide road provides less continuous shade than a connected row of trees. Moreover, a species that grows quickly may require more water than the local climate can supply. Planting without considering these constraints can lead to trees dying before they provide substantial shade.'', nchar(10), nchar(10), N''For this reason, some urban planners combine tree planting with changes to the surfaces beneath them. Permeable paving allows rainfall to reach roots instead of running directly into drains. Such planning treats trees as part of a larger system. The aim is not merely to increase the number planted, but to create conditions in which they can survive and cool streets for decades.''), N''Urban trees and local temperatures'', 3),
    (''68544981-7eb8-bc6b-9ba2-cc0fd04151d8'', N''email'', N''[{"Id":1,"Prompt":"Why was this email sent?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To cancel the club"},{"Id":"B","Text":"To explain a change of activity"},{"Id":"C","Text":"To request camera repairs"},{"Id":"D","Text":"To announce a new starting time"}],"Answer":"B","Explanation":"Hava nedeniyle mek\u00E2n ve etkinlik de\u011Fi\u015Fiyor; ba\u015Flang\u0131\u00E7 saati de\u011Fi\u015Fmiyor."},{"Id":2,"Prompt":"What should participants bring?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Raincoats"},{"Id":"B","Text":"New cameras"},{"Id":"C","Text":"Printed schedules"},{"Id":"D","Text":"Three existing photos"}],"Answer":"D","Explanation":"\u00DC\u00E7 \u00F6nceden \u00E7ekilmi\u015F foto\u011Fraf getirmeleri isteniyor."},{"Id":3,"Prompt":"What remains unchanged?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"The return date for cameras"},{"Id":"B","Text":"The workshop location"},{"Id":"C","Text":"The outdoor activity"},{"Id":"D","Text":"The need to take new pictures"}],"Answer":"A","Explanation":"Kameralar\u0131n pazartesi iade edilmesi originally planned ifadesiyle korunuyor."}]'', N''daily-life'', 2, 2, CONCAT(CAST(N''To: Photography Club'' AS nvarchar(max)), nchar(10), N''Subject: Saturday workshop'', nchar(10), N''Hi everyone,'', nchar(10), N''Because the forecast predicts heavy rain, our outdoor photography session will move to Studio B. The starting time is still 10 a.m. Please bring three photos you have already taken; we will discuss composition instead of taking new pictures. Anyone who borrowed a club camera should return it on Monday, as originally planned.'', nchar(10), N''Maya''), N''A change to the workshop'', 3),
    (''865059ed-7c8d-5859-3fad-54880b77186d'', N''paragraph'', N''[{"Id":1,"Prompt":"Fill in the missing letters.","Prefix":"pot","MissingLetters":4,"Options":[],"Answer":"tery","Explanation":"pottery: broken ile nitelenen topluluk ismi."},{"Id":2,"Prompt":"Fill in the missing letters.","Prefix":"rev","MissingLetters":4,"Options":[],"Answer":"eals","Explanation":"reveals: pottery ile tekil fiil."},{"Id":3,"Prompt":"Fill in the missing letters.","Prefix":"ab","MissingLetters":3,"Options":[],"Answer":"out","Explanation":"about: reveal information about yap\u0131s\u0131."},{"Id":4,"Prompt":"Fill in the missing letters.","Prefix":"li","MissingLetters":2,"Options":[],"Answer":"fe","Explanation":"life: daily life kal\u0131b\u0131."},{"Id":5,"Prompt":"Fill in the missing letters.","Prefix":"expe","MissingLetters":5,"Options":[],"Answer":"nsive","Explanation":"expensive: objects i\u00E7in s\u0131fat."},{"Id":6,"Prompt":"Fill in the missing letters.","Prefix":"bec","MissingLetters":4,"Options":[],"Answer":"ause","Explanation":"because: a\u00E7\u0131klaman\u0131n nedenini ba\u015Flat\u0131r."},{"Id":7,"Prompt":"Fill in the missing letters.","Prefix":"to","MissingLetters":3,"Options":[],"Answer":"ols","Explanation":"tools: common ile \u00E7o\u011Ful isim."},{"Id":8,"Prompt":"Fill in the missing letters.","Prefix":"hab","MissingLetters":3,"Options":[],"Answer":"its","Explanation":"habits: reflect fiilinin nesnesi."},{"Id":9,"Prompt":"Fill in the missing letters.","Prefix":"b","MissingLetters":1,"Options":[],"Answer":"y","Explanation":"by: shared by ile payla\u015Fanlar\u0131 belirtir."},{"Id":10,"Prompt":"Fill in the missing letters.","Prefix":"ordi","MissingLetters":4,"Options":[],"Answer":"nary","Explanation":"ordinary: people i\u00E7in s\u0131fat."}]'', N''complete-words'', 5, 2, N''Archaeologists use ordinary objects to investigate how people lived in the past. Broken {{1}} often {{2}} more {{3}} daily {{4}} than {{5}} objects {{6}} common {{7}} reflect {{8}} shared {{9}} many {{10}} people. A cooking pot may contain traces of food, while worn surfaces can show how an object was handled. Researchers record where each piece was found before removing it. An object loses part of its value as evidence when the relationship between it and the surrounding materials is unknown.'', N''Learning from old objects'', 3),
    (''911d2255-f075-41eb-5140-b11f2cd96377'', N''article'', N''[{"Id":1,"Prompt":"What is the main idea?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Gold is always more informative than pottery"},{"Id":"B","Text":"Chemical tests eliminate uncertainty"},{"Id":"C","Text":"Pottery and its context together reveal past activities"},{"Id":"D","Text":"Broken objects should be discarded"}],"Answer":"C","Explanation":"Hem malzeme hem buluntu ba\u011Flam\u0131 ge\u00E7mi\u015F ya\u015Fam hakk\u0131nda kan\u0131t sunuyor."},{"Id":2,"Prompt":"What might chemical analysis reveal?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"The name of the pot\u0027s owner"},{"Id":"B","Text":"Food or drink residues"},{"Id":"C","Text":"The exact date of every scratch"},{"Id":"D","Text":"The value of gold"}],"Answer":"B","Explanation":"\u0130kinci paragraf yiyecek ve i\u00E7ecek kal\u0131nt\u0131lar\u0131n\u0131 do\u011Frudan belirtir."},{"Id":3,"Prompt":"Why are possible alternative explanations mentioned?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To show why several observations are needed"},{"Id":"B","Text":"To reject all chemical testing"},{"Id":"C","Text":"To prove every pot was buried deliberately"},{"Id":"D","Text":"To explain why records are unnecessary"}],"Answer":"A","Explanation":"Kal\u0131nt\u0131 ve \u00E7iziklerin farkl\u0131 nedenleri olabilece\u011Fi, tek kan\u0131t\u0131n yetersizli\u011Fini g\u00F6steriyor."},{"Id":4,"Prompt":"The word \u0027these\u0027 in \u0027these relationships\u0027 refers to","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Chemical substances"},{"Id":"B","Text":"Improved methods"},{"Id":"C","Text":"Golden ornaments"},{"Id":"D","Text":"Connections between vessels and their surroundings"}],"Answer":"D","Explanation":"\u00D6nceki c\u00FCmle evler ve ortak alanlardaki kaplar\u0131n farkl\u0131 kullan\u0131m ba\u011Flamlar\u0131n\u0131 anlat\u0131yor."},{"Id":5,"Prompt":"Where would this sentence best fit? \u2018Neither kind of evidence offers a complete story on its own.\u2019 Choose a marked location [A]\u2013[D] in the passage.","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Location [A]"},{"Id":"B","Text":"Location [B]"},{"Id":"C","Text":"Location [C]"},{"Id":"D","Text":"Location [D]"}],"Answer":"B","Explanation":"Neither kind iki kan\u0131t t\u00FCr\u00FCne, kimyasal kal\u0131nt\u0131lara ve y\u00FCzey izlerine g\u00F6nderme yapar. [B] bu iki t\u00FCr\u00FCn tan\u0131t\u0131lmas\u0131ndan hemen sonrad\u0131r; sonraki c\u00FCmleler neden tek ba\u015Flar\u0131na kesin sonu\u00E7 vermediklerini a\u00E7\u0131klar."}]'', N''academic-passage'', 3, 2, CONCAT(CAST(N''A broken cooking pot may appear less impressive than a golden ornament, yet it can provide rich evidence about everyday life. Pottery survives in many environments, and even small fragments can preserve traces of how a vessel was made and used. Researchers examine both the material itself and the place where it was discovered.'' AS nvarchar(max)), nchar(10), nchar(10), N''[A] Chemical analysis may reveal residues left by food or drink. Marks on the surface can suggest repeated contact with fire or particular tools. [B] A substance could have entered the pot after it was discarded, while a scratch might have occurred during burial. [C] Researchers therefore compare several independent observations before proposing an explanation.'', nchar(10), nchar(10), N''[D] Location is equally important. Similar vessels found in homes and in communal spaces may have served different purposes. If an object is removed without a record of its surroundings, these relationships can be lost. Careful documentation makes it possible for later researchers to test earlier interpretations using improved methods. Preserving information about an object''''s context can consequently be as valuable as preserving the object itself.''), N''The evidence inside pottery'', 3),
    (''92c7d63a-f66c-44fb-f278-2953b5967fcf'', N''menu'', N''[{"Id":1,"Prompt":"How much does a sandwich and soup cost at 12:00 on Tuesday?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"$7"},{"Id":"B","Text":"$11"},{"Id":"C","Text":"$9"},{"Id":"D","Text":"$13"}],"Answer":"C","Explanation":"Hafta i\u00E7i 11:30\u201314:00 aras\u0131nda ikisi birlikte $9."},{"Id":2,"Prompt":"Who can receive free tea?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Everyone ordering soup"},{"Id":"B","Text":"A student showing a card with a lunch deal"},{"Id":"C","Text":"Anyone visiting after 14:00"},{"Id":"D","Text":"Anyone buying a salad"}],"Answer":"B","Explanation":"\u00DCcretsiz \u00E7ay i\u00E7in hem lunch deal hem \u00F6\u011Frenci kart\u0131 gerekiyor."}]'', N''daily-life'', 3, 2, CONCAT(CAST(N''CAMPUS CAFÉ — LUNCH'' AS nvarchar(max)), nchar(10), N''Soup: $4 | Sandwich: $7 | Salad: $6'', nchar(10), N''Lunch deal: any sandwich + soup for $9, weekdays 11:30–14:00 only.'', nchar(10), N''Tea is $2, or free with a lunch deal when you show a student card.'', nchar(10), N''All items can be ordered separately after 14:00 at their regular prices.''), N''Lunch at the campus café'', 3),
    (''93e23019-d9ed-83e2-ab87-78112f7883af'', N''article'', N''[{"Id":1,"Prompt":"What does the passage explain?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Why all islands have identical habitats"},{"Id":"B","Text":"How isolation and area influence species communities"},{"Id":"C","Text":"Why birds cannot transport seeds"},{"Id":"D","Text":"How farmland increases every population"}],"Answer":"B","Explanation":"Uzakl\u0131k, alan ve kara \u00FCzerindeki habitat par\u00E7alar\u0131 aras\u0131ndaki ba\u011Flant\u0131 ele al\u0131n\u0131yor."},{"Id":2,"Prompt":"Why can small populations be vulnerable?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"They always move too far"},{"Id":"B","Text":"They have too many habitats"},{"Id":"C","Text":"A single event may affect a large part of them"},{"Id":"D","Text":"They cannot use nesting sites"}],"Answer":"C","Explanation":"Tek yuvalama alan\u0131n\u0131n f\u0131rt\u0131nayla yok olmas\u0131 \u00F6rne\u011Fi bu riski g\u00F6steriyor."},{"Id":3,"Prompt":"What does \u0027local disappearances\u0027 mean?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Loss from a particular place"},{"Id":"B","Text":"Extinction across the whole planet"},{"Id":"C","Text":"Seasonal changes in weather"},{"Id":"D","Text":"The formation of new islands"}],"Answer":"A","Explanation":"\u0130kinci paragraf bir adadan kaybolman\u0131n k\u00FCresel yok olu\u015F olmad\u0131\u011F\u0131n\u0131 a\u00E7\u0131klar."},{"Id":4,"Prompt":"Why is a forest surrounded by farms compared to an island?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Both are always surrounded by water"},{"Id":"B","Text":"Both have no birds"},{"Id":"C","Text":"Both contain only one habitat"},{"Id":"D","Text":"The surrounding area may prevent movement"}],"Answer":"D","Explanation":"Tar\u0131m alanlar\u0131n\u0131 ge\u00E7emeyen t\u00FCrler i\u00E7in orman i\u015Flevsel olarak yal\u0131t\u0131lm\u0131\u015Ft\u0131r."},{"Id":5,"Prompt":"What is implied about wildlife corridors?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"They benefit every species equally"},{"Id":"B","Text":"Their usefulness depends on the organism"},{"Id":"C","Text":"They always eliminate local loss"},{"Id":"D","Text":"They are unrelated to movement"}],"Answer":"B","Explanation":"Koridorun yarar\u0131, belirli t\u00FCr\u00FCn nas\u0131l hareket etti\u011Fine ba\u011Fl\u0131d\u0131r."}]'', N''academic-passage'', 4, 2, CONCAT(CAST(N''The number of species on an island reflects a changing balance between arrivals and local disappearances. An island close to a mainland is generally easier for organisms to reach than a distant one. Seeds may travel on wind or birds, while some animals can cross short stretches of water. Distance therefore influences the rate at which new populations become established.'' AS nvarchar(max)), nchar(10), nchar(10), N''Area also matters. Larger islands often contain more types of habitat and can support larger populations. Small populations are more vulnerable to chance events, such as a storm destroying the only nesting site used by a species. A disappearance from one island does not necessarily mean that the species has become extinct everywhere.'', nchar(10), nchar(10), N''These ideas have been applied to habitat fragments on land. A forest surrounded by farms is not literally an island, but species that cannot cross farmland may experience it as one. Creating connections between fragments can make movement easier. Nevertheless, a corridor that benefits one species may not help another. Conservation planning must consider how particular organisms move, rather than assuming that every strip of vegetation provides the same connection.''), N''Why some islands have fewer species'', 3),
    (''a01c9a8e-e268-74e1-f0e6-066ec4706f98'', N''social-post'', N''[{"Id":1,"Prompt":"What is the main purpose of the post?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To sell household items"},{"Id":"B","Text":"To recruit appliance manufacturers"},{"Id":"C","Text":"To invite people to a repair event"},{"Id":"D","Text":"To offer free replacement parts"}],"Answer":"C","Explanation":"Yer, saat ve kat\u0131l\u0131m ko\u015Fullar\u0131 bir onar\u0131m etkinli\u011Fine davet olu\u015Fturuyor."},{"Id":2,"Prompt":"What might a participant have to pay for?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Volunteer advice"},{"Id":"B","Text":"Replacement parts"},{"Id":"C","Text":"An entry ticket"},{"Id":"D","Text":"A reservation"}],"Answer":"B","Explanation":"Tavsiye \u00FCcretsiz; yedek par\u00E7alar\u0131 e\u015Fya sahibi \u00F6d\u00FCyor."},{"Id":3,"Prompt":"What can be inferred about attending without booking?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Repair is guaranteed"},{"Id":"B","Text":"Only experts can attend"},{"Id":"C","Text":"Large items are accepted"},{"Id":"D","Text":"Help may not be available"}],"Answer":"D","Explanation":"Rezervasyonsuz kat\u0131l\u0131mc\u0131lara yaln\u0131zca zaman kal\u0131rsa yard\u0131m ediliyor."}]'', N''daily-life'', 5, 2, CONCAT(CAST(N''COMMUNITY REPAIR DAY — Sunday, 13 October'' AS nvarchar(max)), nchar(10), N''Bring one small household item to the community hall between 10:00 and 15:00. Volunteers will help you try to repair it. Advice is free, but replacement parts are paid for by the owner. No previous repair skills are needed. Booking is recommended; people without a reservation will be helped only if time allows. Please do not bring large appliances.''), N''Volunteer repair day'', 3),
    (''a1b67254-22bb-c34a-536a-dbe31a433274'', N''messages'', N''[{"Id":1,"Prompt":"Where will the students first meet if it rains?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"In Room 12"},{"Id":"B","Text":"In the caf\u00E9"},{"Id":"C","Text":"In the courtyard"},{"Id":"D","Text":"By the library entrance"}],"Answer":"D","Explanation":"Otherwise ifadesi kuru hava ko\u015Fulunun ger\u00E7ekle\u015Fmemesine ba\u011Flan\u0131yor."},{"Id":2,"Prompt":"What has Nora already done?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Uploaded the article"},{"Id":"B","Text":"Printed the charts"},{"Id":"C","Text":"Booked Room 12"},{"Id":"D","Text":"Found an indoor room"}],"Answer":"A","Explanation":"Done ve group folder ifadeleri makalenin \u00E7evrimi\u00E7i payla\u015F\u0131ld\u0131\u011F\u0131n\u0131 g\u00F6steriyor."}]'', N''daily-life'', 4, 2, CONCAT(CAST(N''Nora 16:05: Can we meet in Room 12 at five?'' AS nvarchar(max)), nchar(10), N''Leo 16:08: It is booked until six. The café is noisy today.'', nchar(10), N''Nora 16:10: Let''''s use the library courtyard if it stays dry. Otherwise, meet by the library entrance and we will find a space inside.'', nchar(10), N''Leo 16:12: Great. I''''ll bring the printed charts. Can you share the article online before we meet?'', nchar(10), N''Nora 16:13: Done — check the group folder.''), N''A study group conversation'', 3),
    (''abf3dfbd-c502-4fc3-8d30-d2dd9ced8a75'', N''article'', N''[{"Id":1,"Prompt":"Which approach does the passage favor?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Organizing signs around users\u0027 decisions"},{"Id":"B","Text":"Making every sign brighter than its neighbors"},{"Id":"C","Text":"Displaying all instructions at the entrance"},{"Id":"D","Text":"Removing differences between all destinations"}],"Answer":"A","Explanation":"The text emphasizes hierarchy, relevant locations, consistency and visitor observation."},{"Id":2,"Prompt":"Why is a transport station used as an example?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To explain how stations are constructed"},{"Id":"B","Text":"To show that information is needed in stages"},{"Id":"C","Text":"To compare train and bus prices"},{"Id":"D","Text":"To argue against payment machines"}],"Answer":"B","Explanation":"Visitors first find an area, then a machine, then instructions."},{"Id":3,"Prompt":"What does \u0022burden\u0022 refer to?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"The cost of bright displays"},{"Id":"B","Text":"The distance between buildings"},{"Id":"C","Text":"The difficulty of processing too much information"},{"Id":"D","Text":"The weight of a ticket machine"}],"Answer":"C","Explanation":"The preceding sentences describe too many instructions competing at the entrance."},{"Id":4,"Prompt":"What is one benefit of consistent sign design?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"It removes every need to read"},{"Id":"B","Text":"It guarantees identical destinations"},{"Id":"C","Text":"It makes visitor testing unnecessary"},{"Id":"D","Text":"People can recognize a learned visual pattern"}],"Answer":"D","Explanation":"Visitors can learn the pattern and locate similar information elsewhere."},{"Id":5,"Prompt":"What is implied about designers?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Their familiarity may hide problems newcomers experience"},{"Id":"B","Text":"They always prefer dim signs"},{"Id":"C","Text":"They cannot learn from observation"},{"Id":"D","Text":"They should avoid all visual differences"}],"Answer":"A","Explanation":"A designer knows the building and conventions that a newcomer has not learned."}]'', N''academic-passage'', 8, 2, CONCAT(CAST(N''Designers often make a sign larger or brighter when they want it to be noticed. This strategy can work when the surrounding environment is visually simple. In a crowded setting, however, many signs compete for attention using the same technique. Adding another bright display may contribute to the competition without making useful information easier to find.'' AS nvarchar(max)), nchar(10), nchar(10), N''One alternative is to organize information into a clear hierarchy. A visitor entering a transport station may first need to identify the ticket area, then select a particular machine, and finally read payment instructions. Displaying every instruction at the entrance gives equal visual weight to information needed at different moments. Placing relevant details at the point where a decision is made can reduce this burden.'', nchar(10), nchar(10), N''Consistency also supports navigation. If signs for the same kind of destination share a recognizable design, visitors can learn the pattern and search for it elsewhere. This does not mean every sign should look identical: important differences still need to be visible. Instead, a consistent system helps people predict where to find particular information. Evaluating such a system requires observing actual visitors. A sign that appears obvious to its designer may confuse a newcomer who does not yet understand the building or its conventions.''), N''When a brighter sign attracts less attention'', 3),
    (''b05b1357-9dac-4240-8a4c-5bb8f2546077'', N''paragraph'', N''[{"Id":1,"Prompt":"Complete the missing letters.","Prefix":"volun","MissingLetters":5,"Options":[],"Answer":"teers","Explanation":"The complete word is \u0022volunteers\u0022 in this sentence: Local volunteers interview older residents about changing neighborhoods and record their memories while trained historians compare these stories with written documents."},{"Id":2,"Prompt":"Complete the missing letters.","Prefix":"ol","MissingLetters":3,"Options":[],"Answer":"der","Explanation":"The complete word is \u0022older\u0022 in this sentence: Local volunteers interview older residents about changing neighborhoods and record their memories while trained historians compare these stories with written documents."},{"Id":3,"Prompt":"Complete the missing letters.","Prefix":"ab","MissingLetters":3,"Options":[],"Answer":"out","Explanation":"The complete word is \u0022about\u0022 in this sentence: Local volunteers interview older residents about changing neighborhoods and record their memories while trained historians compare these stories with written documents."},{"Id":4,"Prompt":"Complete the missing letters.","Prefix":"neighb","MissingLetters":7,"Options":[],"Answer":"orhoods","Explanation":"The complete word is \u0022neighborhoods\u0022 in this sentence: Local volunteers interview older residents about changing neighborhoods and record their memories while trained historians compare these stories with written documents."},{"Id":5,"Prompt":"Complete the missing letters.","Prefix":"rec","MissingLetters":3,"Options":[],"Answer":"ord","Explanation":"The complete word is \u0022record\u0022 in this sentence: Local volunteers interview older residents about changing neighborhoods and record their memories while trained historians compare these stories with written documents."},{"Id":6,"Prompt":"Complete the missing letters.","Prefix":"memo","MissingLetters":4,"Options":[],"Answer":"ries","Explanation":"The complete word is \u0022memories\u0022 in this sentence: Local volunteers interview older residents about changing neighborhoods and record their memories while trained historians compare these stories with written documents."},{"Id":7,"Prompt":"Complete the missing letters.","Prefix":"tra","MissingLetters":4,"Options":[],"Answer":"ined","Explanation":"The complete word is \u0022trained\u0022 in this sentence: Local volunteers interview older residents about changing neighborhoods and record their memories while trained historians compare these stories with written documents."},{"Id":8,"Prompt":"Complete the missing letters.","Prefix":"com","MissingLetters":4,"Options":[],"Answer":"pare","Explanation":"The complete word is \u0022compare\u0022 in this sentence: Local volunteers interview older residents about changing neighborhoods and record their memories while trained historians compare these stories with written documents."},{"Id":9,"Prompt":"Complete the missing letters.","Prefix":"sto","MissingLetters":4,"Options":[],"Answer":"ries","Explanation":"The complete word is \u0022stories\u0022 in this sentence: Local volunteers interview older residents about changing neighborhoods and record their memories while trained historians compare these stories with written documents."},{"Id":10,"Prompt":"Complete the missing letters.","Prefix":"wri","MissingLetters":4,"Options":[],"Answer":"tten","Explanation":"The complete word is \u0022written\u0022 in this sentence: Local volunteers interview older residents about changing neighborhoods and record their memories while trained historians compare these stories with written documents."}]'', N''complete-words'', 7, 2, N''An oral history archive preserves accounts that may never appear in official records. Local {{1}} interview {{2}} residents {{3}} changing {{4}} and {{5}} their {{6}} while {{7}} historians {{8}} these {{9}} with {{10}} documents. A remembered date may be inaccurate even when a description of everyday routines is valuable. Interviewers therefore ask open questions and avoid suggesting the answer they expect. The recordings retain the speakers'''' own words. Together with maps and letters, these accounts help future listeners understand how different people experienced the same changes.'', N''An archive of ordinary voices'', 3),
    (''b0dee4db-210a-4f4b-8049-be939c4e8083'', N''notice'', N''[{"Id":1,"Prompt":"What problem are the students trying to solve?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Poor image clarity"},{"Id":"B","Text":"Missing survey data"},{"Id":"C","Text":"Insufficient seats"},{"Id":"D","Text":"An unavailable classroom"}],"Answer":"A","Explanation":"Ravi says the projected graphs are blurry, not that the data are missing."},{"Id":2,"Prompt":"What has Leah already completed?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Inviting the audience"},{"Id":"B","Text":"Printing the notes"},{"Id":"C","Text":"Testing the new PDF"},{"Id":"D","Text":"Exporting the graphs"}],"Answer":"B","Explanation":"Leah says she has printed copies, while the file test is planned for tomorrow."}]'', N''daily-life'', 8, 2, CONCAT(CAST(N''Ravi 14:10: The graphs are ready, but they look blurry on the classroom projector.'' AS nvarchar(max)), nchar(10), N''Leah 14:12: Can you export them as a PDF? That solved the same problem for my last talk.'', nchar(10), N''Ravi 14:15: I will try that tonight. Are you still bringing the speaker notes?'', nchar(10), N''Leah 14:17: Yes. I have printed a copy for each of us. Let us test the new file tomorrow at nine before the audience arrives.''), N''A shared presentation'', 3),
    (''b1e13889-5cf7-45d9-889f-1a863896cf8f'', N''article'', N''[{"Id":1,"Prompt":"What is the main idea?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"An unexpected result invalidates all scientific research"},{"Id":"B","Text":"Differences between models and observations can guide improvements"},{"Id":"C","Text":"Useful models must contain every real-world detail"},{"Id":"D","Text":"Laboratory rivers always predict sediment accurately"}],"Answer":"B","Explanation":"The example shows how a mismatch identifies a missing influence and leads to revision."},{"Id":2,"Prompt":"What feature might explain the unexpected sediment pattern?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"The color of the measuring tools"},{"Id":"B","Text":"A complete absence of flowing water"},{"Id":"C","Text":"Plants along the riverbank"},{"Id":"D","Text":"A change in the laboratory building"}],"Answer":"C","Explanation":"Vegetation can alter flow but was omitted from the channel model."},{"Id":3,"Prompt":"The word \u0022approximation\u0022 is closest in meaning to","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"exact historical record"},{"Id":"B","Text":"complete rejection"},{"Id":"C","Text":"unrelated measurement"},{"Id":"D","Text":"simplified representation"}],"Answer":"D","Explanation":"The revised model includes a representation of plants without reproducing every detail."},{"Id":4,"Prompt":"What can researchers conclude if the revised prediction improves?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Vegetation mattered in the situation studied"},{"Id":"B","Text":"All other omitted features are unimportant"},{"Id":"C","Text":"The model is correct for every river"},{"Id":"D","Text":"Weather can never influence sediment"}],"Answer":"A","Explanation":"The text explicitly limits the finding to the setting and does not dismiss other omissions."},{"Id":5,"Prompt":"How is the second paragraph related to the first?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"It lists all features every model must include"},{"Id":"B","Text":"It illustrates how an omission can become significant"},{"Id":"C","Text":"It argues that simplification is always impossible"},{"Id":"D","Text":"It changes the topic to river tourism"}],"Answer":"B","Explanation":"The first paragraph discusses relevance of omissions; the second supplies a concrete case."}]'', N''academic-passage'', 9, 2, CONCAT(CAST(N''Scientific models simplify complex systems so that particular relationships can be studied. A model of a river, for example, may represent flowing water and movable sediment while leaving out vegetation and changes in weather. Such omissions do not automatically make the model useless. Its value depends on the question being investigated and on whether the omitted features matter for that question.'' AS nvarchar(max)), nchar(10), nchar(10), N''Unexpected results can help researchers identify these limits. Suppose a laboratory channel predicts that sediment will gather at a bend, but observations from a real river show less accumulation. Rather than immediately rejecting every part of the model, researchers can examine the difference. Plants along the real riverbank might change the flow in a way the simplified channel does not represent.'', nchar(10), nchar(10), N''A revised model could then include an approximation of those plants. If its predictions improve, this provides evidence that vegetation was important in that setting. It does not establish that every other omitted feature is irrelevant. Models are therefore often developed through repeated comparison with observations. A mismatch can be productive because it suggests what needs further investigation. The aim is not to reproduce every detail of reality, but to build a representation that is informative for a clearly stated purpose.''), N''A useful mistake in a laboratory model'', 3),
    (''ba5d904d-518c-455d-8012-fd012e29eb71'', N''notice'', N''[{"Id":1,"Prompt":"Who may take seeds home?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Visitors who have brought no seeds"},{"Id":"B","Text":"Only experienced gardeners"},{"Id":"C","Text":"Only people donating three packets"},{"Id":"D","Text":"Only residents with a private garden"}],"Answer":"A","Explanation":"The notice explicitly permits taking three packets without contributing any."},{"Id":2,"Prompt":"What determines the event location?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"The variety of plants"},{"Id":"B","Text":"The weather forecast"},{"Id":"C","Text":"The number of seed packets"},{"Id":"D","Text":"The age of volunteers"}],"Answer":"B","Explanation":"Rain in the forecast triggers a move to the hall."}]'', N''daily-life'', 10, 2, CONCAT(CAST(N''NEIGHBORHOOD SEED EXCHANGE'' AS nvarchar(max)), nchar(10), N''Saturday, 10:00–12:00, East Garden'', nchar(10), N''Label each packet with the plant name and the year the seeds were collected. Bring only seeds from plants you have grown yourself. You may take up to three packets even if you have none to contribute. Volunteers will accept empty paper envelopes for future exchanges. The event will move to the adjacent hall if rain is forecast.''), N''Seed exchange guidelines'', 3),
    (''c2f8fd32-5229-4dea-84f2-2ab31906c1c5'', N''paragraph'', N''[{"Id":1,"Prompt":"Complete the missing letters.","Prefix":"pl","MissingLetters":3,"Options":[],"Answer":"ace","Explanation":"The complete word is \u0022place\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods."},{"Id":2,"Prompt":"Complete the missing letters.","Prefix":"acr","MissingLetters":3,"Options":[],"Answer":"oss","Explanation":"The complete word is \u0022across\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods."},{"Id":3,"Prompt":"Complete the missing letters.","Prefix":"surf","MissingLetters":4,"Options":[],"Answer":"aces","Explanation":"The complete word is \u0022surfaces\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods."},{"Id":4,"Prompt":"Complete the missing letters.","Prefix":"mea","MissingLetters":4,"Options":[],"Answer":"sure","Explanation":"The complete word is \u0022measure\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods."},{"Id":5,"Prompt":"Complete the missing letters.","Prefix":"posi","MissingLetters":5,"Options":[],"Answer":"tions","Explanation":"The complete word is \u0022positions\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods."},{"Id":6,"Prompt":"Complete the missing letters.","Prefix":"sum","MissingLetters":3,"Options":[],"Answer":"mer","Explanation":"The complete word is \u0022summer\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods."},{"Id":7,"Prompt":"Complete the missing letters.","Prefix":"sate","MissingLetters":5,"Options":[],"Answer":"llite","Explanation":"The complete word is \u0022satellite\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods."},{"Id":8,"Prompt":"Complete the missing letters.","Prefix":"rev","MissingLetters":3,"Options":[],"Answer":"eal","Explanation":"The complete word is \u0022reveal\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods."},{"Id":9,"Prompt":"Complete the missing letters.","Prefix":"patt","MissingLetters":4,"Options":[],"Answer":"erns","Explanation":"The complete word is \u0022patterns\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods."},{"Id":10,"Prompt":"Complete the missing letters.","Prefix":"lon","MissingLetters":3,"Options":[],"Answer":"ger","Explanation":"The complete word is \u0022longer\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods."}]'', N''complete-words'', 6, 2, N''A glacier can move so slowly that its motion is difficult to notice. Scientists {{1}} markers {{2}} frozen {{3}} and {{4}} their {{5}} each {{6}} while {{7}} images {{8}} broader {{9}} over {{10}} periods. Measurements from several years help distinguish a brief seasonal change from a lasting trend. A single photograph cannot show how quickly the ice is moving. Researchers also record snowfall because fresh snow may hide the markers. Combining ground observations with images from above gives a more useful account of the glacier than either method alone.'', N''Measuring a moving glacier'', 3),
    (''cccfb12e-890f-4eca-87df-c324dc0312af'', N''article'', N''[{"Id":1,"Prompt":"What is the passage mainly about?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Why seed banks no longer need field research"},{"Id":"B","Text":"How to grow plants without water"},{"Id":"C","Text":"Why seed preservation requires ongoing management"},{"Id":"D","Text":"Why all seeds should be frozen immediately"}],"Answer":"C","Explanation":"Each paragraph explains a component of managing a collection beyond simply keeping it cold."},{"Id":2,"Prompt":"Why do staff test small samples?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To identify the coldest room"},{"Id":"B","Text":"To remove all genetic variation"},{"Id":"C","Text":"To calculate the weight of each packet"},{"Id":"D","Text":"To check whether stored seeds can still grow"}],"Answer":"D","Explanation":"Germination tests indicate whether the seeds can produce seedlings."},{"Id":3,"Prompt":"What does \u0022renewal\u0022 refer to?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Producing a fresh supply of seeds"},{"Id":"B","Text":"Replacing written records"},{"Id":"C","Text":"Cooling an empty container"},{"Id":"D","Text":"Moving packets between rooms"}],"Answer":"A","Explanation":"The preceding sentence describes growing stored seeds into plants that produce new ones."},{"Id":4,"Prompt":"What can be inferred about using very few parent plants?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"The collection will last indefinitely"},{"Id":"B","Text":"Some original genetic variety may be lost"},{"Id":"C","Text":"All seeds will become resistant to drying"},{"Id":"D","Text":"Documentation becomes unnecessary"}],"Answer":"B","Explanation":"A handful of plants may not represent the variety in the original population."},{"Id":5,"Prompt":"Why does the author discuss a packet with no origin information?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To show that germination tests are unreliable"},{"Id":"B","Text":"To explain how cooling changes plant names"},{"Id":"C","Text":"To illustrate the importance of documentation"},{"Id":"D","Text":"To recommend discarding every old packet"}],"Answer":"C","Explanation":"The example links useful research material to reliable records."}]'', N''academic-passage'', 6, 2, CONCAT(CAST(N''Seed banks preserve plant varieties by keeping seeds under controlled conditions. Cooling can slow the chemical reactions associated with aging, but temperature is only one part of the process. Many seeds must also be dried carefully before storage. Too much moisture can damage them, while some species cannot tolerate substantial drying at all.'' AS nvarchar(max)), nchar(10), nchar(10), N''For seeds that respond well to dry, cold storage, a collection is still not a permanent solution. Staff periodically remove small samples and test whether they germinate. If too few seedlings emerge, the remaining seeds may need to be grown into plants that produce a fresh supply. This renewal has to be planned carefully: growing only a handful of plants could fail to preserve the genetic variety present in the original collection.'', nchar(10), nchar(10), N''Records are another essential component. A packet without reliable information about its origin may have limited research value. Knowing where and under what conditions the parent plants grew helps researchers select material for later studies. Thus, a successful seed bank is more than a cold room filled with containers. It is an active system of storage, testing, renewal, and documentation. Different species require different strategies, and even apparently stable collections need continuing attention.''), N''Why stored seeds need more than cold'', 3),
    (''da1689ce-4f1a-506f-3631-49bb772f5b1a'', N''paragraph'', N''[{"Id":1,"Prompt":"Fill in the missing letters.","Prefix":"peo","MissingLetters":3,"Options":[],"Answer":"ple","Explanation":"people: recall fiilinin \u00E7o\u011Ful \u00F6znesi."},{"Id":2,"Prompt":"Fill in the missing letters.","Prefix":"eve","MissingLetters":3,"Options":[],"Answer":"nts","Explanation":"events: hat\u0131rlanan olaylar."},{"Id":3,"Prompt":"Fill in the missing letters.","Prefix":"bra","MissingLetters":3,"Options":[],"Answer":"ins","Explanation":"brains: their sonras\u0131nda \u00E7o\u011Ful isim."},{"Id":4,"Prompt":"Fill in the missing letters.","Prefix":"sto","MissingLetters":3,"Options":[],"Answer":"red","Explanation":"stored: details i\u00E7in ge\u00E7mi\u015Fte depolanm\u0131\u015F anlam\u0131."},{"Id":5,"Prompt":"Fill in the missing letters.","Prefix":"wi","MissingLetters":2,"Options":[],"Answer":"th","Explanation":"with: combine A with B yap\u0131s\u0131."},{"Id":6,"Prompt":"Fill in the missing letters.","Prefix":"know","MissingLetters":5,"Options":[],"Answer":"ledge","Explanation":"knowledge: current s\u0131fat\u0131ndan sonra isim."},{"Id":7,"Prompt":"Fill in the missing letters.","Prefix":"memo","MissingLetters":4,"Options":[],"Answer":"ries","Explanation":"memories: change fiilinin \u00F6znesi."},{"Id":8,"Prompt":"Fill in the missing letters.","Prefix":"cha","MissingLetters":3,"Options":[],"Answer":"nge","Explanation":"change: memories ile yal\u0131n fiil."},{"Id":9,"Prompt":"Fill in the missing letters.","Prefix":"ea","MissingLetters":2,"Options":[],"Answer":"ch","Explanation":"each: her yeni deneyimi belirtir."},{"Id":10,"Prompt":"Fill in the missing letters.","Prefix":"exper","MissingLetters":5,"Options":[],"Answer":"ience","Explanation":"experience: new s\u0131fat\u0131ndan sonra tekil isim."}]'', N''complete-words'', 2, 2, N''Human memory is an active process rather than a perfect recording. When {{1}} recall {{2}} their {{3}} combine {{4}} details {{5}} current {{6}} so {{7}} sometimes {{8}} after {{9}} new {{10}}. This does not mean that every memory is unreliable. Repeated practice can strengthen information that is useful, such as a route to work. Nevertheless, two witnesses may remember the same scene differently because they noticed different details and later discussed the event with other people.'', N''How memories change'', 3),
    (''e108ef5a-f337-46e1-a5ef-73e01ba3fa08'', N''paragraph'', N''[{"Id":1,"Prompt":"Fill in the missing letters.","Prefix":"lea","MissingLetters":3,"Options":[],"Answer":"ves","Explanation":"leaves: g\u00F6lgeyi sa\u011Flayan yapraklar, \u00E7o\u011Ful isim."},{"Id":2,"Prompt":"Fill in the missing letters.","Prefix":"sh","MissingLetters":3,"Options":[],"Answer":"ade","Explanation":"shade: provide fiilinin nesnesi, g\u00F6lge."},{"Id":3,"Prompt":"Fill in the missing letters.","Prefix":"sum","MissingLetters":3,"Options":[],"Answer":"mer","Explanation":"summer: during sonras\u0131nda mevsim ad\u0131."},{"Id":4,"Prompt":"Fill in the missing letters.","Prefix":"wa","MissingLetters":3,"Options":[],"Answer":"ter","Explanation":"water: evaporates fiilinin \u00F6znesi."},{"Id":5,"Prompt":"Fill in the missing letters.","Prefix":"fr","MissingLetters":2,"Options":[],"Answer":"om","Explanation":"from: buharla\u015Fman\u0131n \u00E7\u0131kt\u0131\u011F\u0131 noktay\u0131 belirtir."},{"Id":6,"Prompt":"Fill in the missing letters.","Prefix":"open","MissingLetters":4,"Options":[],"Answer":"ings","Explanation":"openings: tiny ile nitelenen \u00E7o\u011Ful isim."},{"Id":7,"Prompt":"Fill in the missing letters.","Prefix":"co","MissingLetters":3,"Options":[],"Answer":"ols","Explanation":"cools: tekil \u00F6zne water ile uyumlu fiil."},{"Id":8,"Prompt":"Fill in the missing letters.","Prefix":"surro","MissingLetters":6,"Options":[],"Answer":"unding","Explanation":"surrounding: air ismini niteleyen s\u0131fat."},{"Id":9,"Prompt":"Fill in the missing letters.","Prefix":"throu","MissingLetters":5,"Options":[],"Answer":"ghout","Explanation":"throughout: s\u00FCrenin tamam\u0131n\u0131 belirtir."},{"Id":10,"Prompt":"Fill in the missing letters.","Prefix":"d","MissingLetters":2,"Options":[],"Answer":"ay","Explanation":"day: the ile kullan\u0131lan zaman ismi."}]'', N''complete-words'', 1, 2, N''City trees influence the temperature of the streets around them. Their {{1}} provide {{2}} during {{3}} while {{4}} evaporates {{5}} tiny {{6}} and {{7}} the {{8}} air {{9}} the {{10}}. The effect is strongest where several trees grow together. However, trees need enough space for their roots and a reliable supply of water. Planners therefore consider soil conditions as well as appearance when choosing which species to plant along a busy street.'', N''Trees in the city'', 3),
    (''eb7aaaa9-007d-5974-fd3d-e2245160047b'', N''article'', N''[{"Id":1,"Prompt":"What distinction is central to the passage?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Printed versus digital notes"},{"Id":"B","Text":"Familiarity versus unaided recall"},{"Id":"C","Text":"Morning versus evening study"},{"Id":"D","Text":"Science versus history lessons"}],"Answer":"B","Explanation":"\u0130lk paragraf tan\u0131d\u0131kl\u0131k hissi ile yard\u0131ms\u0131z hat\u0131rlaman\u0131n farkl\u0131l\u0131\u011F\u0131n\u0131 kuruyor."},{"Id":2,"Prompt":"Why should learners check answers after retrieval?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To avoid all future effort"},{"Id":"B","Text":"To memorize page numbers"},{"Id":"C","Text":"To identify and correct gaps"},{"Id":"D","Text":"To make sessions longer"}],"Answer":"C","Explanation":"Yan\u0131t\u0131 kaynakla kar\u015F\u0131la\u015Ft\u0131rma, eksikleri ve yanl\u0131\u015Flar\u0131 belirler."},{"Id":3,"Prompt":"What does \u0027accessible\u0027 mean in the final paragraph?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Available to recall"},{"Id":"B","Text":"Printed in large type"},{"Id":"C","Text":"Free to purchase"},{"Id":"D","Text":"Located nearby"}],"Answer":"A","Explanation":"Bilginin zaman ge\u00E7se de hat\u0131rlanabilir olmas\u0131 anlat\u0131l\u0131yor."},{"Id":4,"Prompt":"What can be inferred about an easy study session?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"It must involve retrieval"},{"Id":"B","Text":"It guarantees long-term learning"},{"Id":"C","Text":"It requires no feedback"},{"Id":"D","Text":"It may give a misleading impression of learning"}],"Answer":"D","Explanation":"Kolayl\u0131k ve tan\u0131d\u0131kl\u0131k kal\u0131c\u0131 \u00F6\u011Frenmeyi tek ba\u015F\u0131na kan\u0131tlam\u0131yor."},{"Id":5,"Prompt":"How is the second paragraph organized?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"A historical event followed by dates"},{"Id":"B","Text":"A benefit followed by a condition for its success"},{"Id":"C","Text":"Two unrelated definitions"},{"Id":"D","Text":"A list of examination rules"}],"Answer":"B","Explanation":"Eksikleri g\u00F6rme yarar\u0131 anlat\u0131l\u0131p do\u011Fru geri bildirim ko\u015Fulu ekleniyor."}]'', N''academic-passage'', 2, 2, CONCAT(CAST(N''Students often prepare for an examination by reading their notes repeatedly. This can make the material feel familiar, but familiarity is not the same as being able to recall an idea without help. An alternative approach asks students to close their notes and attempt to explain what they remember. This process is known as retrieval practice.'' AS nvarchar(max)), nchar(10), nchar(10), N''Retrieval can be useful even when the first attempt is incomplete. After answering, a learner checks the original material and identifies gaps. The comparison provides a clearer guide for further study than the general feeling that a page looks familiar. However, feedback matters: repeatedly producing an incorrect answer without checking it may strengthen the error rather than correct it.'', nchar(10), nchar(10), N''Spacing these attempts over several days adds another challenge. Some forgetting occurs between sessions, so recall requires effort again. Although this can feel less comfortable than immediate repetition, it helps reveal whether knowledge remains accessible over time. Effective study therefore involves both attempting to retrieve information and using reliable feedback to refine it, rather than judging success solely by how easy a study session feels.''), N''When retrieval improves learning'', 3),
    (''fc4dc8ce-ffd7-3253-d7be-5daa2263a65a'', N''paragraph'', N''[{"Id":1,"Prompt":"Fill in the missing letters.","Prefix":"ra","MissingLetters":2,"Options":[],"Answer":"in","Explanation":"rain: falls fiilinin \u00F6znesi."},{"Id":2,"Prompt":"Fill in the missing letters.","Prefix":"so","MissingLetters":2,"Options":[],"Answer":"me","Explanation":"some: water i\u00E7in miktar belirten s\u00F6zc\u00FCk."},{"Id":3,"Prompt":"Fill in the missing letters.","Prefix":"mo","MissingLetters":3,"Options":[],"Answer":"ves","Explanation":"moves: water ile tekil fiil."},{"Id":4,"Prompt":"Fill in the missing letters.","Prefix":"sm","MissingLetters":3,"Options":[],"Answer":"all","Explanation":"small: spaces ismini niteler."},{"Id":5,"Prompt":"Fill in the missing letters.","Prefix":"bet","MissingLetters":4,"Options":[],"Answer":"ween","Explanation":"between: kayalar aras\u0131ndaki konumu belirtir."},{"Id":6,"Prompt":"Fill in the missing letters.","Prefix":"wh","MissingLetters":3,"Options":[],"Answer":"ere","Explanation":"where: rocks ile anlat\u0131lan yere ba\u011Flan\u0131r."},{"Id":7,"Prompt":"Fill in the missing letters.","Prefix":"lay","MissingLetters":3,"Options":[],"Answer":"ers","Explanation":"layers: underground s\u0131fat\u0131ndan sonra isim."},{"Id":8,"Prompt":"Fill in the missing letters.","Prefix":"col","MissingLetters":4,"Options":[],"Answer":"lect","Explanation":"collect: layers ile yal\u0131n fiil."},{"Id":9,"Prompt":"Fill in the missing letters.","Prefix":"st","MissingLetters":3,"Options":[],"Answer":"ore","Explanation":"store: collect and store paralel fiiller."},{"Id":10,"Prompt":"Fill in the missing letters.","Prefix":"valu","MissingLetters":4,"Options":[],"Answer":"able","Explanation":"valuable: resource i\u00E7in s\u0131fat."}]'', N''complete-words'', 3, 2, N''Much of the water people use is stored beneath the ground. After {{1}} falls {{2}} water {{3}} through {{4}} spaces {{5}} rocks {{6}} underground {{7}} slowly {{8}} and {{9}} this {{10}} resource. These layers can supply wells even during dry weather. Yet the stored water is not unlimited. If people pump it out faster than rainfall replaces it, the water level drops. Understanding this balance helps communities decide how much water they can safely use for farming and household needs.'', N''Water below the surface'', 3)');
