    EXEC(N'INSERT INTO [content].[WritingQuestionVersions] ([Id], [Context], [Instructions], [Kind], [PostsJson], [PublicationStatus], [QuestionId], [RequirementsJson], [Title], [Version])
    VALUES (''022f9acf-d328-4fe8-8460-89795685767c'', N''Professor: Should all research students receive training in explaining their work to the general public? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"Public communication builds understanding of why research matters."},{"Name":"Omar","Text":"Students already have demanding specialist training and should choose such courses."}]'', 2, ''022f9acf-d328-4fe8-8460-89795685767c'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''Research communication'', 1),
    (''0af9257a-0f0f-4c18-8ff6-866cf8ce6d27'', N''Professor: A university has aging furniture. Should it prioritize repairing existing furniture or buying new items? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"Repair reduces waste and can support skilled local workers."},{"Name":"Omar","Text":"New items may be safer and more comfortable for students."}]'', 2, ''0af9257a-0f0f-4c18-8ff6-866cf8ce6d27'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''Repair or replace'', 1),
    (''14349705-1c8d-4203-89f9-7b165a540107'', N''Professor: Should busy commuter trains include a quiet carriage? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"A quiet area helps passengers rest or concentrate during a long journey."},{"Name":"Omar","Text":"Dividing limited space may cause confusion and disagreements when trains are full."}]'', 2, ''14349705-1c8d-4203-89f9-7b165a540107'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''Quiet transport spaces'', 1),
    (''20aea2bc-baf0-4684-8fc8-6ba7b7969e78'', N''Professor: Should a university invest more in a navigation app or in improved physical signs? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"An app can provide personalized routes and quick updates."},{"Name":"Omar","Text":"Clear signs assist every visitor without requiring a phone or account."}]'', 2, ''20aea2bc-baf0-4684-8fc8-6ba7b7969e78'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''Campus navigation'', 1),
    (''2266e5f3-d570-4983-80da-e4d98d98a829'', N''Your department has paired you with a new exchange student, Jordan, who arrives next week. Write Jordan an email.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''2266e5f3-d570-4983-80da-e4d98d98a829'', N''["Introduce yourself and your role.","Suggest a place and time for a first meeting.","Offer help with one specific aspect of campus life."]'', N''Welcoming an exchange partner'', 1),
    (''26f81fcd-b000-4213-8694-cb6b6f287f9a'', N''Professor: Should a course grade reflect how much a student improves as well as final achievement? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"Recognizing progress rewards effort and encourages struggling learners."},{"Name":"Omar","Text":"A grade should communicate the same final standard for every student."}]'', 2, ''26f81fcd-b000-4213-8694-cb6b6f287f9a'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''Recognizing improvement'', 1),
    (''37537ac0-6963-4acd-8cd0-a2e2e3efdcd6'', N''Professor: Should cities fund projects in which residents collect environmental data? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"Residents can gather observations across places researchers rarely visit."},{"Name":"Omar","Text":"Public funding should prioritize measurements made by trained specialists."}]'', 2, ''37537ac0-6963-4acd-8cd0-a2e2e3efdcd6'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''Community science'', 1),
    (''38565a8b-d806-4d7e-8ac1-6dfb4efeedd9'', N''Professor: Should most campus cultural events be organized by students or professional staff? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"Student leadership builds practical skills and reflects current interests."},{"Name":"Omar","Text":"Professional organizers can provide continuity and dependable arrangements."}]'', 2, ''38565a8b-d806-4d7e-8ac1-6dfb4efeedd9'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''Student-run events'', 1),
    (''3e2a0e60-ff90-4aa8-8b34-ac888c37ca48'', N''Professor: Should universities promote borrowing everyday items through a shared service rather than encourage individual ownership? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"Sharing can save money and reduce unused possessions in small rooms."},{"Name":"Omar","Text":"Convenient access and responsibility for damage may be difficult to manage."}]'', 2, ''3e2a0e60-ff90-4aa8-8b34-ac888c37ca48'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''A campus borrowing culture'', 1),
    (''43337a41-e165-4616-8a84-afbfaac4c9ea'', N''Professor: Should manufacturers be required to provide spare parts for electronic devices for several years? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"Available parts can reduce waste and make ownership more affordable."},{"Name":"Omar","Text":"Maintaining parts for older devices could raise prices for all customers."}]'', 2, ''43337a41-e165-4616-8a84-afbfaac4c9ea'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''Longer equipment life'', 1),
    (''56c06847-adc2-4c3d-8dca-c74c53fea320'', N''Your club borrowed a display board from another student group. One panel was damaged while you were packing it away. Write to the other group''''s representative, Alex.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''56c06847-adc2-4c3d-8dca-c74c53fea320'', N''["Explain what happened.","Apologize and take responsibility.","Offer a specific repair or replacement arrangement."]'', N''Returning a borrowed display'', 1),
    (''5f24bb90-4be5-4d42-86f7-bbd0beb3942e'', N''You noticed that the online campus map directs wheelchair users to an entrance with steps. Write to the accessibility office.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''5f24bb90-4be5-4d42-86f7-bbd0beb3942e'', N''["Describe the incorrect direction.","Explain its likely effect on visitors.","Suggest a correction and offer useful details."]'', N''Improving a campus map'', 1),
    (''6ad4d6ce-5392-4417-823c-5af6e5c695ea'', N''Your class visited a museum exhibition. The objects were interesting, but several labels were hard to read. Write to the visitor experience manager.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''6ad4d6ce-5392-4417-823c-5af6e5c695ea'', N''["Describe something your class appreciated.","Explain the difficulty with the labels.","Suggest a specific improvement."]'', N''Feedback on a museum visit'', 1),
    (''6f2a969d-1685-43af-8700-650fecab2119'', N''Professor: Should public libraries lend practical tools as well as books and digital materials? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"Sharing tools helps residents complete occasional tasks without buying equipment."},{"Name":"Omar","Text":"Libraries should concentrate limited staff time on information services."}]'', 2, ''6f2a969d-1685-43af-8700-650fecab2119'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''Library tool lending'', 1),
    (''718d03e6-c296-4ce4-8e5d-dcc19e6d8608'', N''Professor: Should residents vote directly on public art projects, or should a panel of specialists choose them? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"Residents use the spaces, so their preferences should guide spending."},{"Name":"Omar","Text":"Specialists can recognize artistic value that is not immediately popular."}]'', 2, ''718d03e6-c296-4ce4-8e5d-dcc19e6d8608'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''Public art choices'', 1),
    (''77812661-c57b-4cef-861e-7d09ea04e7ee'', N''A guest speaker gave your student society a useful talk about careers in conservation. Write to Dr. Morgan.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''77812661-c57b-4cef-861e-7d09ea04e7ee'', N''["Thank the speaker for a specific contribution.","Describe how the talk helped the audience.","Ask whether one follow-up resource could be shared."]'', N''Thanking a guest speaker'', 1),
    (''83bb6b42-34ff-47ee-89a5-d961da598131'', N''Professor: Should students review classmates'''' work anonymously? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"Anonymity may make criticism more honest and reduce social pressure."},{"Name":"Omar","Text":"Named feedback encourages accountability and allows follow-up discussion."}]'', 2, ''83bb6b42-34ff-47ee-89a5-d961da598131'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''Anonymous peer review'', 1),
    (''8865979e-a8e5-4dd9-8c50-d569156cf666'', N''You borrowed a recording kit from the media desk and discovered that its charging cable was missing. You need the kit tomorrow. Write to the desk supervisor, Ms. Perez.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''8865979e-a8e5-4dd9-8c50-d569156cf666'', N''["Identify the borrowed kit and missing item.","Explain why the timing matters.","Request a practical solution."]'', N''An incomplete equipment kit'', 1),
    (''91ee691b-73bc-4c81-8924-571110e18c4c'', N''For a class project, you want to interview the manager of a neighborhood repair café. Write to the manager, Mr. Patel.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''91ee691b-73bc-4c81-8924-571110e18c4c'', N''["Introduce the project and its purpose.","Explain what participation would involve.","Ask about a convenient time and offer flexibility."]'', N''Requesting permission to interview'', 1),
    (''98758474-eab6-48d2-89c2-a0a76af17794'', N''You must leave your project team''''s presentation rehearsal early for a previously arranged appointment. Write to your teammates.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''98758474-eab6-48d2-89c2-a0a76af17794'', N''["Explain your availability.","Describe what work you will complete before leaving.","Propose how to receive feedback on the remaining rehearsal."]'', N''A team member leaving early'', 1),
    (''99fa0988-7a14-42ce-886a-3fed1b52b401'', N''A short design workshop was advertised as free, but your confirmation email requests payment. Write to the course administrator, Dr. Ahmed.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''99fa0988-7a14-42ce-886a-3fed1b52b401'', N''["Explain the conflicting information.","Ask what the fee covers and whether it applies to you.","State what information you need before confirming attendance."]'', N''Clarifying a workshop fee'', 1),
    (''aef36905-5781-4c29-87b4-883f7fcf1900'', N''Your student gardening group has spare planting space and wants a local school to participate. Write to the school''''s science teacher, Ms. Brooks.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''aef36905-5781-4c29-87b4-883f7fcf1900'', N''["Explain the opportunity.","Describe one activity pupils could do.","Invite the teacher to discuss practical arrangements."]'', N''A community garden invitation'', 1),
    (''b19b01ff-9441-4a0e-86ce-3b32f6eb49f4'', N''Professor: Would scheduling university classes on four days rather than five benefit students? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"An open weekday would allow longer independent study or work shifts."},{"Name":"Omar","Text":"Longer teaching days could reduce attention and leave students exhausted."}]'', 2, ''b19b01ff-9441-4a0e-86ce-3b32f6eb49f4'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''A four-day study week'', 1),
    (''c8ac1133-6b28-4af7-8119-a7b5ec69ab7a'', N''You ordered a textbook to your residence hall. The tracking page says it was delivered, but the reception desk has no record of it. Write to the bookseller''''s support team.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''c8ac1133-6b28-4af7-8119-a7b5ec69ab7a'', N''["Identify the order and the discrepancy.","Explain what you have already checked.","Ask for the next step in resolving the issue."]'', N''A missed delivery notice'', 1),
    (''cdc03421-9cc6-477f-800e-7f88e3e24f85'', N''You have agreed to volunteer at a weekend science fair, but the required induction overlaps with a compulsory class. Write to the volunteer organizer, Mr. Lewis.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''cdc03421-9cc6-477f-800e-7f88e3e24f85'', N''["Explain the scheduling conflict.","Reaffirm your interest in volunteering.","Propose a way to complete the induction."]'', N''Volunteer induction conflict'', 1),
    (''db96bff3-d303-4904-8077-d4ed84c86043'', N''The student center has very few quiet places to eat during the busiest hour. Write to the center''''s manager, Ms. Osei.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''db96bff3-d303-4904-8077-d4ed84c86043'', N''["Describe the problem from a student\u0027s perspective.","Suggest a feasible change to an existing space.","Explain who would benefit and why."]'', N''Suggesting a quiet lunch area'', 1),
    (''e2bae46b-6b44-4920-8ea2-689cb21d394d'', N''Your student tutoring appointment coincides with a rescheduled laboratory session. Write to your tutor, Sam.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''e2bae46b-6b44-4920-8ea2-689cb21d394d'', N''["Explain why you need to change the appointment.","Suggest two alternative times.","Mention what you would like to work on in the session."]'', N''Changing a tutoring appointment'', 1),
    (''f56a544b-be0a-4765-86bf-07c45afc8444'', N''Professor: Should university lecture attendance be optional when high-quality recordings are available? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"Recordings let students study around work and other responsibilities."},{"Name":"Omar","Text":"Attending together encourages questions and a sense of community."}]'', 2, ''f56a544b-be0a-4765-86bf-07c45afc8444'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''Flexible attendance'', 1),
    (''f8f9a565-bba7-4f61-85bf-c9ea7e9927c0'', N''Professor: Should community centers prioritize activities that mix age groups or programs designed for one age group? Explain and support your view.'', N''Write a contribution in your own words. An effective response will contain at least 100 words; length alone does not determine the score.'', 2, N''[{"Name":"Nina","Text":"Mixed groups allow people to exchange different experiences."},{"Name":"Omar","Text":"Age-specific programs can better match participants\u0027 needs and schedules."}]'', 2, ''f8f9a565-bba7-4f61-85bf-c9ea7e9927c0'', N''["State your position.","Support it with reasoning or an example.","Contribute a new idea to the discussion."]'', N''Learning across generations'', 1),
    (''fd5fea12-a3b1-42ac-8c5b-26455382d2d1'', N''You reserved a room in the arts building to rehearse a small group presentation. Renovation noise made the room unusable. Write to the facilities coordinator, Ms. Chen.'', N''Write an email in English. Address all three points and use an appropriate tone for the recipient.'', 1, N''[]'', 2, ''fd5fea12-a3b1-42ac-8c5b-26455382d2d1'', N''["Describe when the problem occurred and how it affected your group.","Ask for a suitable alternative room.","Suggest how students could be warned about future work."]'', N''A noisy practice space'', 1)');
    IF EXISTS (SELECT * FROM [sys].[identity_columns] WHERE [name] IN (N'Id', N'Context', N'Instructions', N'Kind', N'PostsJson', N'PublicationStatus', N'QuestionId', N'RequirementsJson', N'Title', N'Version') AND [object_id] = OBJECT_ID(N'[content].[WritingQuestionVersions]'))
        SET IDENTITY_INSERT [content].[WritingQuestionVersions] OFF;
END;

